import numpy as np
from scipy import stats

MAX_DRIVERS = 2

def design(feats):
    # Remove near-duplicates based on correlation
    keep = []
    seen = set()
    for i, fid in enumerate(feats.ids):
        if fid in seen:
            continue
        keep.append(i)
        # Check correlations with already-kept features
        for j in range(i+1, len(feats.ids)):
            if feats.ids[j] in seen:
                continue
            corr = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(corr) >= 0.6:
                seen.add(feats.ids[j])

    # Filter to kept features
    kept_ids = [feats.ids[i] for i in keep]
    kept_x = feats.x[:, keep]

    # Compute effect sizes using t-statistics (mean difference / stderr)
    effect_sizes = []
    for i, fid in enumerate(kept_ids):
        y0 = feats.y[feats.x[:,i] < np.median(feats.x[:,i])]
        y1 = feats.y[feats.x[:,i] >= np.median(feats.x[:,i])]
        if len(y0) > 0 and len(y1) > 0:
            t_stat, _ = stats.ttest_ind(y0, y1)
            effect_sizes.append((abs(t_stat), i, fid))
        else:
            effect_sizes.append((0, i, fid))

    # Sort by effect size
    effect_sizes.sort(reverse=True)

    # Select top features for drivers
    drivers = tuple([fid for _, _, fid in effect_sizes[:MAX_DRIVERS]])

    # For columns, use all features with |t| > 1.5 or p < 0.05
    columns = []
    products = []
    loadings = {}

    # Use a simpler approach: just select top features with good statistical significance
    # Keep at most 5 features in columns to avoid overfitting
    top_features = effect_sizes[:5]  # Top 5 features

    for _, i, fid in top_features:
        y0 = feats.y[feats.x[:,i] < np.median(feats.x[:,i])]
        y1 = feats.y[feats.x[:,i] >= np.median(feats.x[:,i])]
        if len(y0) > 0 and len(y1) > 0:
            t_stat, p_val = stats.ttest_ind(y0, y1)
            if abs(t_stat) > 1.5 or p_val < 0.05:
                columns.append(fid)
                loadings[fid] = t_stat

    # Add interaction terms only between top 3 features
    if len(columns) >= 2:
        for i in range(min(3, len(columns))):
            for j in range(i+1, min(3, len(columns))):
                products.append((columns[i], columns[j]))

    # Ensure we don't exceed reasonable limits
    if len(columns) > 5:
        columns = columns[:5]
    if len(products) > 5:
        products = products[:5]

    return Design(
        drivers=drivers,
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

